Review this JavaScript function and list ALL correctness bugs you can find. Be concise, one short line per bug.
function average(nums) {
  let sum = 0;
  for (let i = 0; i <= nums.length; i++) { sum += nums[i]; }
  const avg = sum / nums.length - 1;
  return avg;
}

